import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. PALETTE & CONFIG
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Dimensions of the List Row (designed to span highly visible horizontal space in the hub frame)
  const width = 6.2;
  const height = 0.9;

  // Active GSAP animations registry for clean disposal
  const activeTimelines = [];

  // 2. STAGE/BACKDROP & BASE ROW CONTAINER
  // We construct an interactive plate representing the list row
  const rowGeometry = new PlaneGeometry(width, height);
  const rowMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.9
  });
  const rowPlate = new Mesh(rowGeometry, rowMaterial);
  group.add(rowPlate);

  // Subtle divider at the bottom of the row
  const dividerGeom = new PlaneGeometry(width, 0.02);
  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.15
  });
  const divider = new Mesh(dividerGeom, dividerMat);
  divider.position.set(0, -height / 2, 0.01);
  group.add(divider);

  // Subtle interactive accent edge (will illuminate on hover)
  const edgeGeom = new PlaneGeometry(0.04, height * 0.82);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0
  });
  const accentEdge = new Mesh(edgeGeom, edgeMat);
  accentEdge.position.set(-width / 2 + 0.1, 0, 0.02);
  group.add(accentEdge);

  // 3. TEXT RENDERING (Verbatim / Typographic Balance)
  const titleText = ctx.fontAtlas.createText('CHRONOGRAPH II: MONOLITH', {
    fontSize: 22,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-width / 2 + 0.3, 0.1, 0.02);
  group.add(titleText);

  const metaText = ctx.fontAtlas.createText('CALIBRE NA-01 / STEEL-EDITION', {
    fontSize: 11,
    color: colors.paper,
    align: 'left'
  });
  // Dim the metadata for visual hierarchy
  metaText.children.forEach(c => {
    if (c.material) {
      c.material.transparent = true;
      c.material.opacity = 0.55;
    }
  });
  metaText.position.set(-width / 2 + 0.3, -0.19, 0.02);
  group.add(metaText);

  const priceText = ctx.fontAtlas.createText('CHF 8,400', {
    fontSize: 15,
    color: colors.paper,
    align: 'right'
  });
  priceText.position.set(width / 2 - 0.4, -0.05, 0.02);
  group.add(priceText);

  // Load and apply the optional brushed metal texture map if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      rowMaterial.colorNode = null; // override flat color logic
      rowMaterial.color = new Color('#323238'); // base material colorization
      rowMaterial.map = texture;
      rowMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  // 4. BEHAVIORS & INTERACTIONS
  const state = { hovered: false, active: false };

  const onOver = () => {
    if (state.active) return;
    state.hovered = true;

    const tl = gsap.timeline();
    tl.to(group.position, { z: 0.15, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(rowMaterial, { opacity: 1.0, duration: 0.3 }, 0);
    tl.to(accentEdge.material, { opacity: 1.0, duration: 0.25 }, 0);
    tl.to(dividerMat, { opacity: 0.4, duration: 0.3 }, 0);
    activeTimelines.push(tl);
  };

  const onOut = () => {
    state.hovered = false;
    const tl = gsap.timeline();
    tl.to(group.position, { z: 0.0, duration: 0.4, ease: 'power3.out' }, 0);
    tl.to(rowMaterial, { opacity: 0.9, duration: 0.4 }, 0);
    tl.to(accentEdge.material, { opacity: 0.0, duration: 0.3 }, 0);
    tl.to(dividerMat, { opacity: 0.15, duration: 0.4 }, 0);
    activeTimelines.push(tl);
  };

  const onClick = () => {
    state.active = true;
    const tl = gsap.timeline({
      onComplete: () => {
        state.active = false;
        ctx.emit('hub-collection.select', { item: 'chronograph-monolith', price: 8400 });
      }
    });
    tl.to(group.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.1, ease: 'power1.out' });
    tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'back.out(1.8)' });
    activeTimelines.push(tl);
  };

  // Wire pointers relative to the main interactive plate
  group.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // 5. CLEANUP DESTRUCTOR
  group.userData.cleanup = () => {
    activeTimelines.forEach(t => t.kill());
    rowGeometry.dispose();
    rowMaterial.dispose();
    dividerGeom.dispose();
    dividerMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();
    if (rowMaterial.map) {
      rowMaterial.map.dispose();
    }
  };

  return group;
}
